<script setup lang="ts">
import {ref,onMounted,watch} from 'vue'
import {ElMessage} from 'element-plus'
import {api,useAuth} from './api'
import LearningReport from './LearningReport.vue'
const report=ref<any>(null), reportOpen=ref(false), reportLoading=ref(false)
const sessionList=ref<any[]>([]), sessionsOpen=ref(false)
async function showReport(){reportLoading.value=true;try{report.value=await api(`/sessions/${session.value.id}/report`);reportOpen.value=true}catch(e){fail(e)}finally{reportLoading.value=false}}
async function showSessions(){try{sessionList.value=await api('/sessions?page_size=50');sessionsOpen.value=true}catch(e){fail(e)}}
async function resumeSession(id:number){try{const result=await api('/sessions/'+id);await selectArticle(result.article_id);scene.value=result.scene;session.value=result;await readMessages();sessionsOpen.value=false}catch(e){fail(e)}}
const auth=useAuth(), registering=ref(false), busy=ref(false), generating=ref(false), sending=ref(false)
const credentials=ref({username:'',password:'',email:''})
const articles=ref<any[]>([]), article=ref<any>(null), scenes=ref<any[]>([]), scene=ref<any>(null)
const session=ref<any>(null), messages=ref<any[]>([]), content=ref(''), page=ref(1), difficulty=ref('standard')
const upload=ref(false), draft=ref({title:'',content:'',level:'B1',source:'user_upload'})
function fail(e:unknown){ElMessage.error(e instanceof Error?e.message:'请求失败，请检查后端是否启动')}
async function login(){busy.value=true;try{if(registering.value){await api('/auth/register','POST',credentials.value);ElMessage.success('注册成功，正在登录')};const result=await api('/auth/login','POST',credentials.value);auth.setToken(result.access_token);await init()}catch(e){fail(e)}finally{busy.value=false}}
async function init(){try{const me=await api('/users/me');auth.username=me.username;await load()}catch(e){fail(e)}}
async function load(){articles.value=await api(`/articles?page=${page.value}&page_size=10`)}
async function changePage(n:number){page.value=n;try{await load()}catch(e){fail(e)}}
async function selectArticle(id:number){try{article.value=await api('/articles/'+id);scene.value=null;session.value=null;messages.value=[];scenes.value=await api('/scenes?article_id='+id)}catch(e){fail(e)}}
async function save(){busy.value=true;try{const a=await api('/articles','POST',draft.value);upload.value=false;page.value=1;await load();await selectArticle(a.id);ElMessage.success('文章已保存到数据库')}catch(e){fail(e)}finally{busy.value=false}}
async function generate(){generating.value=true;try{scene.value=await api('/scenes/generate','POST',{article_id:article.value.id,difficulty:difficulty.value});scenes.value=await api('/scenes?article_id='+article.value.id);session.value=null;messages.value=[];ElMessage.success('场景已生成并保存')}catch(e){fail(e)}finally{generating.value=false}}
async function selectScene(id:number){try{scene.value=await api('/scenes/'+id);session.value=null;messages.value=[]}catch(e){fail(e)}}
async function readMessages(){let all:any[]=[];let offset=0;while(true){const batch=await api<any[]>(`/sessions/${session.value.id}/messages?limit=100&offset=${offset}`);all.push(...batch);if(batch.length<100)break;offset+=100}messages.value=all}
async function enter(){busy.value=true;try{session.value=await api('/sessions','POST',{article_id:article.value.id,scene_id:scene.value.id});await readMessages()}catch(e){fail(e)}finally{busy.value=false}}
async function send(){if(!content.value.trim())return;sending.value=true;try{await api(`/sessions/${session.value.id}/messages`,'POST',{content:content.value});content.value=''}catch(e){fail(e)}finally{try{await readMessages()}catch(e){fail(e)}sending.value=false}}
watch(()=>auth.token,t=>{if(!t){reportOpen.value=false;report.value=null;sessionsOpen.value=false;sessionList.value=[];articles.value=[];article.value=null;scene.value=null;session.value=null;messages.value=[]}})
onMounted(()=>{if(auth.token)init()})
</script>
<template>
 <div class="shell">
  <header><a class="brand" href="/">语境<span>CONTEXT LAB</span></a><div class="header-right"><span>文章 → 场景 → 对话</span><template v-if="auth.token"><b>{{auth.username}}</b><el-button text @click="showSessions">我的学习会话</el-button><el-button text @click="auth.logout()">退出登录</el-button></template><a href="http://127.0.0.1:8000/docs" target="_blank" rel="noopener">接口文档 ↗</a></div></header>
  <main v-if="!auth.token" class="welcome"><section><div class="eyebrow">READ. IMAGINE. SPEAK.</div><h1>把读过的文章，<br>变成你说出的英语。</h1><p>从一篇真实文章出发，进入专属的角色场景。<br>表达观点、解决分歧，在对话中练习。</p><div class="steps"><span>01 阅读文章</span><span>02 生成场景</span><span>03 开始对话</span></div></section><section class="login card"><h2>{{registering?'创建学习账号':'欢迎回来'}}</h2><p>登录后，开启你的下一段练习。</p><el-form label-position="top" @submit.prevent="login"><el-form-item label="用户名"><el-input v-model="credentials.username" placeholder="至少 3 个字符" autocomplete="username" /></el-form-item><el-form-item v-if="registering" label="邮箱"><el-input v-model="credentials.email" type="email" placeholder="you@example.com" /></el-form-item><el-form-item label="密码"><el-input v-model="credentials.password" type="password" show-password placeholder="至少 6 个字符" autocomplete="current-password" /></el-form-item><el-button type="primary" native-type="submit" :loading="busy" class="wide">{{registering?'注册并登录':'登录'}}</el-button><el-button text class="wide" @click="registering=!registering">{{registering?'已有账号？去登录':'还没有账号？创建账号'}}</el-button></el-form></section></main>
  <main v-else class="workspace">
   <aside class="card library"><div class="section-top"><h2>文章库</h2><el-button type="primary" size="small" @click="upload=true">＋ 新文章</el-button></div><p class="muted">登录用户共享的阅读素材</p><div v-if="!articles.length" class="empty">还没有文章，先添加一篇英文素材。</div><button v-for="a in articles" :key="a.id" class="article-row" :class="{active:article?.id===a.id}" @click="selectArticle(a.id)"><span class="level">{{a.level}}</span><strong>{{a.title}}</strong><small>{{a.created_at.slice(0,10)}}</small></button><div class="pager"><el-button :disabled="page===1" @click="changePage(page-1)">上一页</el-button><span>{{page}}</span><el-button :disabled="articles.length<10" @click="changePage(page+1)">下一页</el-button></div></aside>
   <div class="reading"><section v-if="!article" class="card empty large"><div class="eyebrow">YOUR NEXT CONVERSATION</div><h2>从左侧选择一篇文章</h2><p>或添加你感兴趣的英文内容，生成自己的练习场景。</p></section><template v-else><section class="card"><div class="eyebrow">01 / ARTICLE · {{article.level}}</div><h1 class="article-title">{{article.title}}</h1><p class="article-content">{{article.content}}</p><div class="generate-bar"><el-select v-model="difficulty" style="width:150px"><el-option label="入门 simple" value="simple"/><el-option label="标准 standard" value="standard"/><el-option label="挑战 challenge" value="challenge"/></el-select><el-button type="primary" :loading="generating" @click="generate">{{generating?'千问正在设计场景…':'生成学习场景'}}</el-button></div></section><section class="card"><div class="eyebrow">02 / SCENARIO</div><h2>场景卡</h2><p v-if="!scenes.length" class="muted">点击上方按钮，基于文章生成角色、冲突与任务。</p><div class="scene-tabs"><el-button v-for="s in scenes" :key="s.id" :type="scene?.id===s.id?'primary':'default'" plain @click="selectScene(s.id)">{{s.title}}</el-button></div><template v-if="scene"><h3>{{scene.title}}</h3><div class="scene-grid"><div><small>你的身份</small><p>{{scene.user_role}}</p></div><div><small>核心目标</small><p>{{scene.goal}}</p></div><div><small>核心冲突</small><p>{{scene.conflict}}</p></div><div><small>语言目标</small><p>{{scene.language_goals}}</p></div></div><h4>与你对话的角色</h4><div v-for="role in scene.ai_roles" :key="role.name" class="role"><b>{{role.name}}</b> · {{role.stance}}<blockquote>{{role.example}}</blockquote></div><h4>任务链</h4><ol><li v-for="step in scene.task_chain" :key="step.stage"><b>{{step.stage}} · {{step.task}}</b><p>{{step.user_action}}</p></li></ol><p><b>最终产出：</b>{{scene.final_output}}</p><el-button type="primary" :loading="busy" @click="enter">{{session?'重新加载对话记录':'进入场景，开始练习 →'}}</el-button></template></section></template></div>
   <aside class="card conversation"><div class="eyebrow">03 / CONVERSATION</div><h2>对话练习</h2><p class="muted">你的会话与消息仅自己可见</p><div v-if="!session" class="empty">选好场景后，点击「进入场景」开始。</div><template v-else><div class="chat-history"><p v-if="!messages.length" class="muted">用英文向场景中的角色打个招呼吧。</p><div v-for="m in messages" :key="m.id" class="bubble" :class="m.role"><small>{{m.role==='user'?'你':'场景角色'}}</small><p>{{m.content}}</p></div></div><el-input v-model="content" type="textarea" :rows="3" maxlength="2000" placeholder="Write your next line…" :disabled="sending"/><el-button class="wide" type="primary" :loading="sending" :disabled="!content.trim()" @click="send">发送</el-button><el-button class="wide" :loading="reportLoading" :disabled="sending" @click="showReport">查看学习报告</el-button><p class="muted tiny">回复失败时，你的消息仍会保留。可刷新记录确认。</p></template></aside>
  </main>
  <el-dialog v-model="reportOpen" title="本次学习报告" width="min(760px, 95vw)"><LearningReport :report="report"/></el-dialog>
  <el-dialog v-model="sessionsOpen" title="我的学习会话（最近 50 条）" width="min(640px, 95vw)"><p v-if="!sessionList.length">还没有学习会话。选择文章和场景后开始练习。</p><div v-for="s in sessionList" :key="s.id" class="section-top" style="padding:12px 0"><span>会话 #{{s.id}} · 场景 #{{s.scene_id}} · {{s.updated_at.slice(0,10)}}</span><el-button @click="resumeSession(s.id)">继续学习</el-button></div></el-dialog>
  <el-dialog v-model="upload" title="添加英文文章" width="min(640px, 94vw)"><el-form label-position="top" @submit.prevent="save"><el-form-item label="标题"><el-input v-model="draft.title" maxlength="200" /></el-form-item><el-form-item label="正文（至少 20 字符）"><el-input v-model="draft.content" type="textarea" :rows="9" maxlength="15000" show-word-limit /></el-form-item><el-form-item label="英语水平"><el-select v-model="draft.level"><el-option v-for="l in ['A1','A2','B1','B2','C1','C2']" :label="l" :value="l" :key="l"/></el-select></el-form-item><el-form-item label="来源"><el-input v-model="draft.source" maxlength="200"/></el-form-item><el-button type="primary" native-type="submit" :loading="busy">保存文章</el-button></el-form></el-dialog>
 </div>
</template>
